import{_ as e,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"云网络：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","frontmatter":{"title":"云网络：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","showdocs":{"topics":[{"id":"cloud-network","title":"云网络","link":"/topics/cloud-network/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"云网络机制与任务课程","summary":"把维护动作、症状调查和同一故障场景的验收放在一起。","status":"active","related":[{"title":"云网络：配置双向连通路径与访问规则","link":"/systems/cloud-infrastructure/cloud-network/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"云网络：配置双向连通路径与访问规则 · 拓扑文件与边界至完整隔离VPC配置","link":"/systems/cloud-infrastructure/cloud-network/plus/practice/application-part-01","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"云网络：配置双向连通路径与访问规则 · 完整源码、配置与依赖至核对资料与相邻阅读","link":"/systems/cloud-infrastructure/cloud-network/plus/practice/application-part-02","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"云网络：基础对象与机制","link":"/systems/cloud-infrastructure/cloud-network/packet-path","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"云网络：配置双向连通路径与访问规则 · 完整源码、配置与依赖至核对资料与相邻阅读","link":"/systems/cloud-infrastructure/cloud-network/plus/practice/application-part-02"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"云网络：配置双向连通路径与访问规则 · 完整源码、配置与依赖至核对资料与相邻阅读","link":"/systems/cloud-infrastructure/cloud-network/plus/practice/application-part-02"},"next":false},"headers":[],"relativePath":"systems/cloud-infrastructure/cloud-network/operations.md","filePath":"systems/cloud-infrastructure/cloud-network/operations.md"}'),l={name:"systems/cloud-infrastructure/cloud-network/operations.md"};function o(n,a,s,c,p,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="云网络-发布、排障与恢复练习" tabindex="-1">云网络：发布、排障与恢复练习 <a class="header-anchor" href="#云网络-发布、排障与恢复练习" aria-label="Permalink to &quot;云网络：发布、排障与恢复练习&quot;">​</a></h1><h2 id="part-1" tabindex="-1">网络隔离、路由变更与恢复 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;网络隔离、路由变更与恢复 {#part-1}&quot;">​</a></h2><p>维护VPC 双向路径工作表前先保存子网/网卡关联、路由、安全组与 NACL，恢复后以5432 请求与客户端临时端口的回包规则验收。具体配置见<a href="/systems/cloud-infrastructure/cloud-network/plus/practice/application#files">配套示例</a>。</p><p>核对日期2026-10-17；适用范围：以AWS VPC/EC2 2016-11-15 API对象模型为固定示例，核对2026-10-17官方中英文网络ACL/安全组资料；不是跨云通用配置或云端当前最新部署模板。示例未执行；真实环境仍需验证产品配置、权限、连通与恢复结果。先读<a href="/systems/cloud-infrastructure/cloud-network/packet-path#part-1-scope">起点</a>理解前置，再按章节完成推演。</p><h3 id="part-1-isolation" tabindex="-1">网络隔离与最小放行 <a class="header-anchor" href="#part-1-isolation" aria-label="Permalink to &quot;网络隔离与最小放行 {#part-1-isolation}&quot;">​</a></h3><p>云网络隔离将数据库入站限为应用安全组和所需端口，运维通道单独控制；不把0.0.0.0/0作为排障默认。出站控制同样要考虑依赖、更新和审计，全部拒绝可能破坏DNS或身份服务。安全组不是应用鉴权，允许TCP连接仍需数据库身份与加密。共享安全组修改前先列出所有关联对象，避免一条规则同时暴露多服务。</p><h3 id="part-1-change" tabindex="-1">变更、回退与关联 <a class="header-anchor" href="#part-1-change" aria-label="Permalink to &quot;变更、回退与关联 {#part-1-change}&quot;">​</a></h3><p>云网络变更先保存原路由、规则号、网卡与子网关联，按单一目标路径修改最小集合，再检查正反向。替换路由表关联会影响整个子网，新增更长前缀可能截走现有流量；先审计覆盖范围而不是仅看新增一行。回退应恢复准确旧关联及规则，不能删除整个共享表重建。此课程没有执行任何控制面操作，工作表只保留可审阅设计。</p><h3 id="part-1-flow" tabindex="-1">流日志和可观测证据 <a class="header-anchor" href="#part-1-flow" aria-label="Permalink to &quot;流日志和可观测证据 {#part-1-flow}&quot;">​</a></h3><p>云网络流日志记录部分元数据与接受/拒绝判定，适合关联五元组，不等同于完整报文和应用响应。没有记录可能是采集范围、延迟、过滤或平台排除，并不自动说明没有流量。将UTC时间窗、接口ID、方向和动作与路由/规则快照关联；导出前处理地址敏感性，不把用户载荷加入报告。DNS日志与应用错误分别补充不同层证据。</p><h3 id="part-1-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-1-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-1-selfcheck}&quot;">​</a></h3><p>练习：新增更长前缀路由只会影响新建主机吗？</p><details><summary>参考解答</summary><p>不是。已有子网流量也可能按最长前缀被改道，须审计覆盖范围并保留原表/关联以便回退。</p></details><h3 id="part-1-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-1-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-1-references}&quot;">​</a></h3><ul><li><a href="https://docs.aws.amazon.com/zh_cn/vpc/latest/userguide/infrastructure-security.html" target="_blank" rel="noopener noreferrer">AWS VPC 基础设施安全（中文）</a></li><li><a href="https://docs.aws.amazon.com/vpc/latest/userguide/vpc-network-acls.html" target="_blank" rel="noopener noreferrer">网络ACL边界</a></li><li><a href="https://docs.aws.amazon.com/zh_cn/vpc/latest/userguide/vpc-network-acls.html" target="_blank" rel="noopener noreferrer">中文ACL说明</a></li></ul><p>继续阅读<a href="/systems/cloud-infrastructure/cloud-network/packet-path#part-2-routes">机制</a>、<a href="/systems/cloud-infrastructure/cloud-network/plus/practice/application#files">完整实践</a>、<a href="#part-1-isolation">运维</a>、<a href="#part-2-timeout">诊断</a>与<a href="#part-3-exercise">复习</a>。</p><h2 id="part-2" tabindex="-1">解析、超时与回包路径排障 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;解析、超时与回包路径排障 {#part-2}&quot;">​</a></h2><p>本节沿5432 请求与客户端临时端口的回包规则定位失败层；先确认子网/网卡关联、路由、安全组与 NACL，与<a href="/systems/cloud-infrastructure/cloud-network/plus/practice/application#files">配套示例</a>逐项对照，再选择最小修复。</p><h3 id="part-2-timeout" tabindex="-1">连接超时的路径排查 <a class="header-anchor" href="#part-2-timeout" aria-label="Permalink to &quot;连接超时的路径排查 {#part-2-timeout}&quot;">​</a></h3><p>云网络超时排查先确认DNS答案符合目标环境，再沿源路由、双方过滤和返回临时端口逐跳核对。没有SYN-ACK可能是目标未监听、回包阻断或路径不通，不足以断定数据库坏了。避免同时放宽所有规则导致无法证明哪一步有问题。工作表missing-return-nacl案例演示正向都放行而返回失败，真实故障还需授权的报文/流日志证据。</p><h3 id="part-2-refused" tabindex="-1">ConnectionRefused与过滤 <a class="header-anchor" href="#part-2-refused" aria-label="Permalink to &quot;ConnectionRefused与过滤 {#part-2-refused}&quot;">​</a></h3><p>云网络拒绝连接通常意味着收到RST等明确拒绝信号，但中间设备也可能生成拒绝，不能无证据断定一定来自数据库进程。检查目的地址端口、监听、OS防火墙策略和网络设备；超时更常见于丢弃，但两者不是绝对一一对应。安全组Allow只表示此层许可，不能启动应用。把网络层问题与认证失败分开，后者通常发生在连接建立之后。</p><h3 id="part-2-stale" tabindex="-1">DNS旧值与非对称路径 <a class="header-anchor" href="#part-2-stale" aria-label="Permalink to &quot;DNS旧值与非对称路径 {#part-2-stale}&quot;">​</a></h3><p>云网络旧解析排查记录查询名称、解析器、答案、TTL、私有zone关联和应用缓存，避免只清浏览器DNS却遗漏服务进程缓存。双向路由不对称不一定失败，但经过有状态设备时可能影响连接状态；跨VPC或VPN要核对回程与NAT地址转换。练习：改安全组能修复错误DNS答案吗？参考解答：不能，先修复命名和缓存边界，再检查通往正确地址的路径。</p><h3 id="part-2-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-2-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-2-selfcheck}&quot;">​</a></h3><p>练习：超时就代表安全组阻断吗？</p><details><summary>参考解答</summary><p>不能单凭超时断定。DNS错误、缺路由、NACL回包、OS过滤或未监听都可能造成相似现象。</p></details><h3 id="part-2-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-2-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-2-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p><h2 id="part-3" tabindex="-1">入站已放行但连接超时的复盘 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;入站已放行但连接超时的复盘 {#part-3}&quot;">​</a></h2><p>以下演练将VPC 双向路径工作表的变更、失败证据和恢复验收串起来；先熟悉<a href="/systems/cloud-infrastructure/cloud-network/plus/practice/application#files">配套示例</a>中的子网/网卡关联、路由、安全组与 NACL。演练未执行。</p><h3 id="part-3-incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#part-3-incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#part-3-incident-scenario}&quot;">​</a></h3><p>已经放行业务端口，客户端连接仍然超时。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h3 id="part-3-incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#part-3-incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#part-3-incident-evidence}&quot;">​</a></h3><ol><li>核对 DNS 结果、源和目标地址、协议及端口，确认安全组与 ACL 绑定到实际网络接口和子网。</li><li>分别检查请求和回包的路由、网关与规则；以 AWS 网络 ACL 为例，它不因允许请求就自动允许回包。</li><li>对比主机监听、流日志与客户端时间窗口，区分没有路由、策略拒绝和应用无响应。</li></ol><h3 id="part-3-incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#part-3-incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#part-3-incident-recovery}&quot;">​</a></h3><p>按双向路径修正最小必要规则或路由，保留管理链路和旧配置；不要把所有来源与所有端口同时放开作为长期修复。</p><p>验收：批准源可完成业务请求及返回，隔离源仍被拒绝，相关日志能够解释允许和拒绝；平台差异在变更记录中明确。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://docs.aws.amazon.com/vpc/latest/userguide/vpc-network-acls.html" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h3 id="part-3-exercise" tabindex="-1">回包端口练习 <a class="header-anchor" href="#part-3-exercise" aria-label="Permalink to &quot;回包端口练习 {#part-3-exercise}&quot;">​</a></h3><p>云网络端口练习：app49152连db5432，db出站NACL只允许5432能放回包吗？参考解答：不能，返回目标是app49152，应按实际客户端临时范围及目的网段许可；不能因为服务器源端口是5432就把ACL目标端口也写5432。安全组有状态与ACL无状态是两个独立判断，缺一不可。</p><h3 id="part-3-answer" tabindex="-1">路由与授权练习 <a class="header-anchor" href="#part-3-answer" aria-label="Permalink to &quot;路由与授权练习 {#part-3-answer}&quot;">​</a></h3><p>云网络路由练习：数据库私有地址加安全组全开放就能公网访问吗？参考解答：不能，公网还需可路由地址、网关与路由，而全开放又扩大攻击面。应保持私有数据库，通过授权的应用或受控运维路径进入。路由能到达不代表业务已授权，也不代表TLS验证或数据库账号正确。</p><h3 id="part-3-boundary" tabindex="-1">跨云与运行边界 <a class="header-anchor" href="#part-3-boundary" aria-label="Permalink to &quot;跨云与运行边界 {#part-3-boundary}&quot;">​</a></h3><p>云网络复核边界要求每个结论注明云平台、对象关联与正反向证据。课程采用AWS语义和自定义JSON工作表，不将它当成阿里云/华为云通用配置；IPv6、跨区域、VPN/BGP、NAT容量及真实连通性没有运行验收。旧CDN材料属于网络专题参考，缓存调度不是本工作表的VPC路由，不复制产品菜单或历史正文。</p><h3 id="part-3-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-3-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-3-selfcheck}&quot;">​</a></h3><p>练习：app49152到db5432，回包目标端口是什么？</p><details><summary>参考解答</summary><p>49152。NACL目标端口要匹配客户端临时端口，服务器源5432不代表返回目标也是5432。</p></details><h3 id="part-3-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-3-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-3-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p>',51)])])}const f=e(l,[["render",o]]);export{h as __pageData,f as default};
